code.source:
class Square:
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side * self.side

class Circle:
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return round(3.14159 * self.radius ** 2, 2)

shapes = [Square(3), Circle(2), Square(4)]
for shape in shapes:
    print(type(shape).__name__, shape.area())

class Duck:
    def speak(self):
        return "Quack"

class Robot:
    def speak(self):
        return "Beep"

class Rock:
    pass

def talk(thing):
    return thing.speak()

print(talk(Duck()))
print(talk(Robot()))
print(hasattr(Rock(), "speak"))

